INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(52854600, 'Tenyi Spirit - Suruya', '天威龙－素露雅', '天威龍－スールヤ', 'Tuner Monster', 'Wyrm', 'LIGHT', 4, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：幻龙族怪兽或除效果怪兽以外的表侧表示怪兽在自己场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡作为幻龙族同调怪兽的同调素材送去墓地的场合才能发动。从额外卡组把1只「天威」连接怪兽特殊召唤。那之后，自己失去这个效果特殊召唤的怪兽的连接标记数量×1000基本分。这个效果特殊召唤的怪兽不能作为连接素材。'),
(23431858, 'Tenyi Spirit - Vishuda', '天威龙－暝虚堕', '天威龍－ヴィシュダ', 'Effect Monster', 'Wyrm', 'DARK', 7, 1500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有效果怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有效果怪兽以外的表侧表示怪兽存在的场合，把手卡·墓地的这张卡除外，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(77946022, 'Tenyinfinity', '天威无穷之境地', '天威無窮の境地', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「虚空之龙轮」或「天幻之龙轮」加入手卡。 ②：把自己场上1只幻龙族怪兽解放，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：自己结束阶段才能发动。这张卡送去墓地，从自己的卡组·墓地把1张「天威无崩之地」在自己的场地区域表侧表示放置。'),
(54631834, 'Terminal World', '终端世界', '端末世界', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己主要阶段1才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，双方的主要阶段2跳过。'),
(48605591, 'Terminal World NEXT', '终端世界二代', '端末世界NEXT', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上没有其他卡存在，对方场上的怪兽是3只以下，对方场上的魔法·陷阱卡是3张以下的场合才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，双方场上能出的怪兽变成各自最多到3只，双方场上能出的魔法·陷阱卡变成各自最多到3张。'),
(26509612, 'Terra Firma Gravity', '地球重力', 'アース・グラビティ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡不在对方回合的战斗阶段不能发动。可以攻击的4星以下的怪兽必须对自己场上表侧表示存在的「元素英雄 地球侠」作出攻击。'),
(63308047, 'Terra the Terrible', '魔人 泰拉', '魔人 テラ', 'Normal Monster', 'Fiend', 'DARK', 4, 1200, 1300, '住在沼泽地的恶魔手下，看起来不怎么强，但绝不能对他轻心大意。'),
(73628505, 'Terraforming', '星球改造', 'テラ・フォーミング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1张场地魔法卡加入手卡。'),
(56681873, 'Terratiger, the Empowered Warrior', '魔装战士 地虎', '魔装戦士 テライガー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1200, '①：这张卡召唤成功时才能发动。从手卡把1只4星以下的通常怪兽守备表示特殊召唤。'),
(77428945, 'Terrene Toothed Tsuchinoko', '土地锯', '土地鋸', 'Effect Monster', 'Reptile', 'EARTH', 3, 1600, 500, '这张卡特殊召唤成功时，这张卡以外的场上的特殊召唤的怪兽全部变成里侧守备表示。「土地锯」的效果1回合只能使用1次。'),
(69724380, 'Terrible Deal', '魔之取引', '魔の取引', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的魔法卡发动时支付1000基本分才能发动。对方随机丢弃1张手卡。'),
(48468330, 'Terrifying Toddler of Torment', '魔神童', '魔神童', 'Flip Effect Monster', 'Fiend', 'DARK', 3, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡·卡组送去墓地的场合才能发动。这张卡里侧守备表示特殊召唤。 ②：这张卡反转的场合才能发动。从卡组把1只恶魔族怪兽送去墓地。'),
(75294187, 'Terrifying Trap Hole Nightmare', '狂惑落穴', '狂惑の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方对怪兽的特殊召唤成功的回合，以对方场上1只攻击力2000以上的怪兽为对象才能发动。那只怪兽破坏。那之后，自己墓地有「洞」通常陷阱卡或者「落穴」通常陷阱卡存在的场合，可以从对方墓地选1只怪兽除外。'),
(300104002, 'Terror from the Deep!', NULL, NULL, 'Skill Card', 'Mako', NULL, NULL, NULL, NULL, NULL),
(6075533, 'Terror of Trishula', '三叉龙的鼓动', 'トリシューラの鼓動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的「冰结界」同调怪兽种类的以下效果适用。 ●1种类以上：对方场上1张卡除外。 ●2种类以上：对方墓地1张卡除外。 ●3种类以上：对方手卡随机1张除外。 ②：自己场上的「冰结界」同调怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，把墓地的这张卡除外才能发动。那个效果无效。'),
(35975813, 'Terrorking Archfiend', '灭绝国王恶魔', 'ジェノサイドキングデーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 2000, 1500, '这张卡仅当自己场上存在名称中含有「恶魔」字样的怪兽卡时才能进行召唤·反转召唤。这张卡的控制者在自己的每1个准备阶段支付800基本分。当这张卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出2或5，则使此效果无效并将其破坏。被这张卡战斗破坏的效果怪兽的效果无效化。'),
(78060096, 'Terrorking Salmon', '灭绝国王鲑', 'ジェノサイドキングサーモン', 'Normal Monster', 'Fish', 'WATER', 5, 2400, 1000, '作为暗黑海之主令人恐惧的巨大鲑鱼。它的卵作为暗黑界第一美味而闻名。'),
(6589707, 'Terrors in the Hidden City', '地中界的厄灾', '地中界の厄災', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的里侧守备表示怪兽不会成为对方的效果的对象。 ②：只要这张卡在魔法与陷阱区域存在，让在这张卡表侧表示存在期间反转过的自己场上的怪兽的攻击力·守备力上升1500。 ③：魔法与陷阱区域的这张卡被对方的效果破坏的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。'),
(85698115, 'Terrors of the Afterroot', '幽世断离', '幽世離レ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方墓地1只怪兽为对象才能发动。那只怪兽在对方场上特殊召唤。那之后，可以把对方场上1只怪兽除外。那个场合，再让对方的除外状态的1只怪兽回到墓地。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己墓地1只1星怪兽为对象才能发动。那只怪兽回到卡组。那之后，可以从卡组把「常世离」「现世离」「幽世离」的其中1张在自己场上盖放。'),
(63086455, 'Terrors of the Overroot', '现世断离', '現世離レ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1张卡和对方墓地1张卡为对象才能发动。作为对象的场上的卡送去墓地，作为对象的墓地的卡在对方场上盖放。'),
(11110218, 'Terrors of the Underroot', '常世断离', '常世離レ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方墓地最多5张卡为对象，并以那个数量的对方的除外状态的卡为对象才能发动。作为对象的墓地的卡除外，作为对象的除外状态的卡回到墓地。'),
(67584223, 'Tessera the Primal Squire', '源帝从骑特塞拉', '源帝従騎テセラ', 'Effect Monster', 'Warrior', 'LIGHT', 1, 800, 1000, '这个卡名的①②③的效果1回合各能使用1次。 ①：把手卡1张「帝王」魔法·陷阱卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。进行1只怪兽的上级召唤。 ③：这张卡被送去墓地的场合才能发动。从卡组把1只攻击力800/守备力1000的怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(3030892, 'Test Ape', '奴隶猿', 'スレイブ・エイプ', 'Effect Monster', 'Beast', 'EARTH', 2, 700, 300, '这张卡被战斗破坏送去墓地时，可以从卡组把1只名字带有「剑斗兽」的4星以下怪兽在自己场上特殊召唤。'),
(62076252, 'Test Bear', '奴隶熊', 'スレイブベアー', 'Effect Monster', 'Beast', 'EARTH', 4, 900, 600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：从卡组·额外卡组特殊召唤的「剑斗兽」怪兽在自己场上存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放，从自己的手卡·场上（表侧表示）让1只「剑斗兽」怪兽回到卡组·额外卡组才能发动。把最多2只「剑斗兽」怪兽当作「剑斗兽」怪兽的效果的特殊召唤从卡组特殊召唤。'),
(66863374, 'Test Panther', '奴隶豹', 'スレイブパンサー', 'Link Monster', 'Beast', 'EARTH', NULL, 800, NULL, '包含「剑斗兽」怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「剑斗兽」卡加入手卡。 ②：以自己场上1只「剑斗兽」怪兽为对象才能发动。那只「剑斗兽」怪兽回到持有者卡组，原本卡名和那只怪兽不同的1只「剑斗兽」怪兽当作「剑斗兽」怪兽的效果的特殊召唤从卡组特殊召唤。'),
(92373006, 'Test Tiger', '奴隶虎', 'スレイブタイガー', 'Effect Monster', 'Beast', 'EARTH', 3, 600, 300, '①：自己场上有「剑斗兽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放，以自己场上1只「剑斗兽」怪兽为对象才能发动。那只自己的「剑斗兽」怪兽回到持有者卡组，从卡组把1只「剑斗兽」怪兽特殊召唤。这个效果特殊召唤的怪兽变成当作用「剑斗兽」怪兽的效果特殊召唤使用。'),
(501000004, 'Testament of the Arcane Lords', NULL, NULL, 'Effect Monster', 'Spellcaster', 'LIGHT', 10, 3000, 3000, NULL),
(74952447, 'Testudo erat Numen', '曾被称为神的龟', 'かつて神と呼ばれた亀', 'Effect Monster', 'Aqua', 'WATER', 1, NULL, 1800, '只要这张卡在场上表侧表示存在，双方不能把攻击力1800以上的怪兽特殊召唤。'),
(87148330, 'Tethys, Goddess of Light', '光神 忒堤斯', '光神テテュス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2400, 1800, '①：自己抽卡时，那卡是天使族怪兽的场合，把那张卡给对方观看才能发动。这张卡在场上表侧表示存在的场合，自己从卡组抽1张。'),
(16469012, 'Teva', '提婆', 'テーヴァ', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2000, 1500, '①：这张卡上级召唤成功的场合发动。下次的对方回合，对方不能攻击宣言。'),
(74210057, 'Texchanger', '纹理转换蛙', 'テクスチェンジャー', 'Effect Monster', 'Cyberse', 'DARK', 1, 100, 100, '①：1回合1次，自己怪兽被选择作为攻击对象时才能发动。那次攻击无效。那之后，从自己的手卡·卡组·墓地选1只电子界族通常怪兽特殊召唤。'),
(40253382, 'TG-SX1', 'TG-SX1', 'TG－SX1', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「科技属」的怪兽战斗破坏对方怪兽送去墓地时才能发动。选择自己墓地存在的1只名字带有「科技属」的同调怪兽特殊召唤。'),
(76641981, 'TG1-EM1', 'TG1-EM1', 'TG1－EM1', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上存在的1只怪兽和自己场上表侧表示存在的1只名字带有「科技属」的怪兽发动。选择的怪兽的控制权交换。'),
(11264180, 'TGX1-HL', 'TGX1-HL', 'TGX1－HL', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「科技属」的怪兽发动。选择的怪兽的攻击力·守备力变成一半，场上存在的1张魔法·陷阱卡破坏。'),
(3868277, 'TGX3-DX2', 'TGX3-DX2', 'TGX3－DX2', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的3只名字带有「科技属」的怪兽发动。选择的怪兽加入卡组洗切。那之后，从自己卡组抽2张卡。'),
(58258899, 'TGX300', 'TGX300', 'TGX３００', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「科技属」的怪兽每有1只，自己场上表侧表示存在的怪兽的攻击力上升300。'),
(11110587, 'That Grass Looks Greener', '邻人割草', '隣の芝刈り', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己卡组的数量比对方多的场合才能发动。直到卡组数量变成和对方相同为止，从自己卡组上面把卡送去墓地。'),
(39454112, 'That Six', '胡出乱目', '出たら目', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己或者对方掷骰子的场合，可以把那之内1个数目作为以下数目适用。 ●1·3·5出现的场合：当作6使用。 ●2·4·6出现的场合：当作1使用。'),
(22869904, 'That Wacky Alchemy!', '魔力诱爆', '魔力誘爆', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的魔法与陷阱卡区域表侧表示存在的魔法卡被送去墓地的场合才能发动。选择场上表侧表示存在的1只怪兽破坏。'),
(50427388, 'That Wacky Magic!', '暴走的魔力', '暴走する魔力', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地的魔法卡全部从游戏中除外才能发动。持有除外的魔法卡数量×300的数值以下的守备力的对方场上表侧表示存在的怪兽全部破坏。'),
(52367652, 'That Which Feeds on Life', '食命者', '命を食する者', 'Normal Monster', 'Fiend', 'DARK', 4, 1200, 1000, '嗜食所有生物的灵魂，将将其作为自己的能量。'),
(97223101, 'That''s 10!', 'BBS', 'BBS', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次「快回揭示板」以外的卡的效果发动才能发动。给这张卡放置1个访问指示物（最多10个）。 ②：自己场上的怪兽的攻击力上升这张卡的访问指示物数量×100。 ③：这张卡有访问指示物被放置，那些访问指示物数量变成10的场合才能发动。这张卡回到手卡，把持有把自身作为怪兽特殊召唤效果的1张永续陷阱卡从卡组到自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(32864, 'The 13th Grave', '第13人的埋葬者', '１３人目の埋葬者', 'Normal Monster', 'Zombie', 'DARK', 3, 1200, 900, '原本没有任何人的一零三号墓地突然出现的丧尸。'),
(403847, 'The A. Forces', '联合军', '連合軍', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上的战士族怪兽的攻击力上升自己场上的战士族·魔法师族怪兽数量×200的数值。'),
(5141117, 'The Abyss Dragon Swordsoul', '深渊的相剑龙', '深淵の相剣龍', 'Effect Monster', 'Wyrm', 'FIRE', 8, 3000, 2900, '这张卡不能通常召唤，用幻龙族怪兽的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：卡的效果让怪兽被表侧除外的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡特殊召唤的场合，以场地区域1张卡和对方的场上·墓地1只怪兽为对象才能发动。那些卡除外。'),
(70410002, 'The Accumulator', '累加器人', 'ザ・アキュムレーター', 'Effect Monster', 'Thunder', 'LIGHT', 1, NULL, NULL, '①：这张卡的攻击力上升场上的连接怪兽的连接标记数量×300。'),
(64734921, 'The Agent of Creation - Venus', '创造之代行者 维纳斯', '創造の代行者 ヴィーナス', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1600, NULL, '①：支付500基本分才能发动。从手卡·卡组把1只「神圣球体」特殊召唤。'),
(99054885, 'The Agent of Destruction - Venus', '破坏之代行者 维纳斯', '破壊の代行者 ヴィーナス', 'Tuner Monster', 'Fairy', 'DARK', 3, NULL, 1600, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己墓地把1只「创造之代行者 维纳斯」除外才能发动。这张卡从手卡特殊召唤。 ②：支付500的倍数的基本分，从自己墓地的怪兽以及除外的自己怪兽之中以支付的基本分每500为1只的「神圣球体」为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合回到持有者卡组最下面。'),
(97750534, 'The Agent of Entropy - Uranus', '死之代行者 乌拉诺斯', '死の代行者 ウラヌス', 'Tuner Monster', 'Fairy', 'DARK', 5, 2200, 1200, '①：场上有「天空的圣域」存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，自己主要阶段才能发动。从卡组把1只「代行者」怪兽送去墓地。这张卡的等级变成和那只怪兽的等级相同。'),
(91123920, 'The Agent of Force - Mars', '力之代行者 玛尔斯', '力の代行者 マーズ', 'Effect Monster', 'Fairy', 'LIGHT', 3, NULL, NULL, '①：场上的这张卡不受魔法卡的效果影响。 ②：自己场上有「天空的圣域」存在，自己基本分比对方多的场合，这张卡的攻击力·守备力上升那个相差数值。'),
(91345518, 'The Agent of Judgment - Saturn', '裁决之代行者 萨图恩', '裁きの代行者 サターン', 'Effect Monster', 'Fairy', 'LIGHT', 6, 2400, NULL, '①：把这张卡解放才能发动。自己基本分比对方多的场合，给与对方那个相差数值的伤害。这个效果在自己场上有「天空的圣域」存在的场合才能发动和处理。这个效果发动的回合，自己不能进行战斗阶段。'),
(38529357, 'The Agent of Life - Neptune', '命之代行者 尼普顿', '命の代行者 ネプチューン', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从自己的手卡·墓地选「命之代行者 尼普顿」以外的1只「代行者」怪兽特殊召唤。场上或者墓地有「天空的圣域」存在的场合，可以把特殊召唤的怪兽改成1只「许珀里翁」怪兽。直到对方回合结束时，双方不能把这个效果特殊召唤的怪兽解放。 ②：这张卡被除外的场合才能发动。从卡组把1张「天空的圣域」加入手卡。'),
(28573958, 'The Agent of Miracles - Jupiter', '奇迹之代行者 朱庇特', '奇跡の代行者 ジュピター', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 1000, '①：1回合1次，从自己墓地把1只「代行者」怪兽除外，以自己场上1只天使族·光属性怪兽为对象才能发动。那只自己的天使族·光属性怪兽的攻击力直到回合结束时上升800。 ②：1回合1次，从手卡丢弃1只天使族怪兽，以除外的1只自己的天使族·光属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在场上有「天空的圣域」存在的场合才能发动和处理。'),
(91188343, 'The Agent of Mystery - Earth', '神秘之代行者 厄斯', '神秘の代行者 アース', 'Tuner Monster', 'Fairy', 'LIGHT', 2, 1000, 800, '①：这张卡召唤成功时才能发动。从卡组把「神秘之代行者 厄斯」以外的1只「代行者」怪兽加入手卡。场上有「天空的圣域」存在的场合，可以把加入手卡的怪兽改成1只「主宰者·许珀里翁」。'),
(38730226, 'The Agent of Wisdom - Mercury', '英知之代行者 墨丘利', '英知の代行者 マーキュリー', 'Effect Monster', 'Fairy', 'LIGHT', 4, NULL, 1700, '①：对方回合结束时，这张卡在自己的怪兽区域表侧表示存在，自己手卡是0张的场合，下次的自己准备阶段发动。自己从卡组抽1张。'),
(32269855, 'The All-Seeing White Tiger', '独眼白虎', '隻眼のホワイトタイガー', 'Normal Monster', 'Beast', 'WIND', 3, 1300, 500, '对有些人来说感到恐怖，对有些人来说却是尊敬的对象，孤傲的丛林之王。'),
(11738489, 'The Arrival Cyberse @Ignister', '到临电子界＠伊格尼斯者', 'ジ・アライバル・サイバース＠イグニスター', 'Link Monster', 'Cyberse', 'DARK', NULL, NULL, NULL, '属性不同的怪兽3只以上 ①：「电子界到临者@火灵天星」在自己场上只能有1只表侧表示存在。 ②：这张卡的原本攻击力变成作为这张卡的连接素材的怪兽数量×1000。 ③：这张卡不受其他卡的效果影响。 ④：1回合1次，以这张卡以外的场上1只怪兽为对象才能发动。那只怪兽破坏，在作为这张卡所连接区的自己场上把1只「@火灵天星衍生物」（电子界族·暗·1星·攻/守0）特殊召唤。'),
(70493141, 'The Ascended of Thunder', '雷仙神', '雷仙神', 'Effect Monster', 'Thunder', 'LIGHT', 7, 2700, 2400, '①：这张卡可以支付3000基本分从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤的这张卡被对方破坏的场合发动。自己回复5000基本分。'),
(14466224, 'The Atmosphere', '大气圈神鸟', 'The アトモスフィア', 'Effect Monster', 'Winged Beast', 'WIND', 8, 1000, 800, '这张卡不能通常召唤。把自己场上存在的2只怪兽和自己墓地存在的1只怪兽从游戏中除外的场合可以特殊召唤。1回合1次，可以把对方场上表侧表示存在的怪兽当作装备卡使用只有1只给这张卡装备。这张卡的攻击力·守备力上升这张卡的效果装备的怪兽的各自数值。'),
(73680966, 'The Beginning of the End', '终结之起始', '終わりの始まり', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有暗属性怪兽7只以上存在的场合，把那之内的5只除外才能发动。自己从卡组抽3张。'),
(24348204, 'The Bewitching Phantom Thief', '魅惑的怪盗', '魅惑の怪盗', 'Normal Monster', 'Spellcaster', 'DARK', 2, 700, 700, '披着黑色披风装模作样的怪盗。挥着手杖迷惑对方。'),
(82386016, 'The Big Cattle Drive', '乌合之行进', '烏合の行進', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有兽族·兽战士族·鸟兽族的其中任意的怪兽存在的场合，那些种族每有1种类从卡组抽1张卡。这张卡发动的回合，自己不能把其他的魔法·陷阱卡的效果发动。'),
(1689516, 'The Big March of Animals', '百兽大行进', '百獣大行進', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示的兽族怪兽的攻击力，在结束阶段前提升自己场上兽族怪兽数目×200的数值。'),
(34004470, 'The Big Saturn', '大土星', 'The big SATURN', 'Effect Monster', 'Machine', 'DARK', 8, 2800, 2200, '这张卡不能作从手卡·卡组的特殊召唤。丢弃1张手卡并支付1000基本分。直到结束阶段时这张卡的攻击力上升1000。这个效果1回合只有1次在自己的主要阶段才能使用。对方控制的卡的效果把这张卡破坏送去墓地时，双方受到那个攻击力数值的伤害。'),
(71107816, 'The Bistro Butcher', '恶魔烹调师', '悪魔の調理師', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 1000, '这张卡给与对方战斗伤害时，对方在卡组最上面抽2张卡。'),
(49299410, 'The Black Goat Laughs', '嗤嗤黑羊猜猜其名', '嗤う黒山羊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：宣言1个怪兽卡名才能发动。这个回合，双方不能把原本卡名和宣言的怪兽相同的怪兽从墓地以外特殊召唤。 ②：把墓地的这张卡除外，宣言1个怪兽卡名才能发动。这个回合，双方不能把原本卡名和宣言的怪兽相同的怪兽的场上发动的效果发动。'),
(66574418, 'The Black Stone of Legend', '传说的黑石', '伝説の黒石', 'Effect Monster', 'Dragon', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡解放才能发动。从卡组把1只7星以下的「真红眼」怪兽特殊召唤。 ②：这张卡在墓地存在的场合，以自己墓地1只7星以下的「真红眼」怪兽为对象才能发动。那只怪兽回到卡组，这张卡加入手卡。'),
(15033525, 'The Blazing Mars', '烈焰火星', 'The blazing MARS', 'Effect Monster', 'Pyro', 'FIRE', 8, 2600, 2200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，从自己墓地把这张卡以外的3只怪兽除外才能发动。这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。 ②：自己主要阶段1，把自己场上的其他怪兽全部送去墓地才能发动。给与对方为送去墓地的怪兽数量×500伤害。'),
(458748, 'The Book of the Law', '法之圣典', '法の聖典', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只「召唤兽」怪兽解放才能发动。原本属性和解放的怪兽不同的1只「召唤兽」怪兽当作融合召唤从额外卡组特殊召唤。'),
(85182315, 'The Breaking Ruin God', '粉碎的破坏神', '粉砕せし破壊神', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，那些发动和效果不会被无效化。 ①：从自己的手卡·墓地选1只「欧贝利斯克之巨神兵」特殊召唤。这个效果特殊召唤的怪兽在这个回合不受对方的效果影响。 ②：自己场上有「欧贝利斯克之巨神兵」存在的状态，自己为让卡的效果发动而把自己场上的怪兽2只以上同时解放的场合，把墓地的这张卡除外才能发动。对方墓地的怪兽全部除外，给与对方那个数量×500伤害。'),
(69120785, 'The Bystial Alba Los', '深渊兽 阿尔白・洛斯', '深淵の獣アルバ・ロス', 'Effect Monster', 'Dragon', 'LIGHT', 12, 3500, 3500, '这张卡不能通常召唤。把自己场上2只「深渊之兽」怪兽解放的场合才能从手卡·墓地特殊召唤。 ①：只要这个方法特殊召唤的这张卡在怪兽区域存在，场上的表侧表示的仪式·融合·同调·超量·连接怪兽的效果无效化。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。直到对方结束阶段，双方的额外卡组的里侧的卡全部表侧除外。'),
(45005708, 'The Bystial Aluber', '深渊兽 阿卢绯尔', '深淵の獣アルベル', 'Tuner Monster', 'Dragon', 'DARK', 4, 1800, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「阿不思的落胤」使用。 ②：这张卡召唤·特殊召唤的场合，可以丢弃1张手卡，以对方的场上·墓地1只龙族怪兽为对象，从以下效果选择1个发动。 ●这张卡送去墓地，作为对象的场上的怪兽的控制权直到结束阶段得到。 ●这张卡送去墓地，作为对象的墓地的怪兽在自己场上特殊召唤。'),
(32731036, 'The Bystial Lubellion', '深渊兽 卢绯里昂', '深淵の獣ルベリオン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2500, 3000, '这张卡不能通常召唤。「深渊之兽 赫界龙」1回合1次在把自己场上1只6星以上的龙族·暗属性怪兽解放的场合才能从手卡·墓地特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡送去墓地才能发动。从卡组把「深渊之兽 赫界龙」以外的1只「深渊之兽」怪兽加入手卡。 ②：自己主要阶段才能发动。从卡组把1张「烙印」永续魔法·永续陷阱卡在自己场上表侧表示放置。'),
(51196174, 'The Calculator', '计算器人', 'ザ・カリキュレーター', 'Effect Monster', 'Thunder', 'LIGHT', 2, -1, NULL, '①：这张卡的攻击力变成自己场上的怪兽的等级合计×300。'),
(54706054, 'The Calibrator', '测量器人', 'ザ・キャリブレーター', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1500, 1500, '这张卡的攻击力上升对方场上的超量怪兽的阶级合计×300的数值。'),
(90488465, 'The Chaos Creator', '混沌创世神', '混沌の創世神', 'Effect Monster', 'Thunder', 'DARK', 8, 2300, 3000, '这张卡不能通常召唤。从自己墓地把光属性和暗属性的怪兽各1只除外的场合可以特殊召唤。这个卡名的效果1回合只能使用1次。 ①：从手卡特殊召唤的这张卡存在的场合，从除外的自己以及对方的怪兽之中以合计3只为对象才能发动（同名卡最多1张）。那之内的1只在自己场上特殊召唤，剩余用喜欢的顺序回到持有者卡组最下面。'),
(41142615, 'The Cheerful Coffin', '开朗的殡葬师', '陽気な葬儀屋', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己的手卡中丢弃最多3张怪兽卡送去墓地。'),
(64927055, 'The Chorus in the Sky', '天空的歌声', '天空の歌声', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付1000基本分，以自己墓地1只天使族怪兽为对象才能发动。那只怪兽加入手卡。那之后，场上或者墓地有「天空的圣域」存在的场合，可以从除外的自己的卡之中选1张「天空的圣域」或者有那个卡名记述的卡加入手卡。'),
(46232525, 'The Claw of Hermos', '赫谟之爪', 'ヘルモスの爪', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的卡名在规则上也当作「传说之龙 赫谟」使用。「赫谟之爪」在1回合只能发动1张。 ①：「赫谟之爪」的效果才能特殊召唤的融合怪兽卡记述的种族的1只怪兽从自己的手卡·场上送去墓地（那张卡在场上盖放的场合，翻开确认）。那之后，把那1只融合怪兽从额外卡组特殊召唤。'),
(11802691, 'The Continuing Epic of Charles', '查理史诗', 'シャルルの叙事詩', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1张「圣剑」装备魔法卡给对方观看，从手卡·卡组把1只「焰圣骑士」怪兽特殊召唤。那之后，给人观看的卡给那只怪兽装备或送去墓地。 ②：把墓地的这张卡除外，以自己场上1只「焰圣骑士帝-查理」为对象才能发动。从手卡·卡组选1只「圣骑士」怪兽当作攻击力上升500的装备魔法卡使用给作为对象的怪兽装备。'),
(61505339, 'The Creator', '创世神', '創世神', 'Effect Monster', 'Thunder', 'LIGHT', 8, 2300, 3000, '选择自己墓地的1张怪兽卡。将1张手卡送去墓地，选择的那张怪兽卡特殊召唤。这个效果1个回合只能使用1次。这张卡不能从墓地特殊召唤。'),
(97093037, 'The Creator Incarnate', '创世者的化身', '創世者の化身', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1500, '可以把这张卡作祭品，从手卡特殊召唤1只「创世神」。'),
(67809530, 'The Crimson King', NULL, NULL, 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2500, NULL),
(48386462, 'The Cuckoo Commanded to Croon', '啼矣杜鹃', '鳴いて時鳥', 'Effect Monster', 'Winged Beast', 'FIRE', 3, 800, 1000, '这个卡名的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●这张卡破坏。那之后，自己抽1张。 ●选自己1张手卡丢弃。那之后，自己抽1张。 ●这个回合的结束阶段，自己抽1张。'),
(52101615, 'The Dark - Hex-Sealed Fusion', '融合咒印生物－暗', '融合呪印生物－闇', 'Effect Monster', 'Rock', 'DARK', 3, 1000, 1600, '①：这张卡可以作为融合怪兽卡有卡名记述的1只融合素材怪兽的代替。那个时候，其他的融合素材怪兽必须是正规品。 ②：把暗属性融合怪兽卡决定的一组融合素材怪兽（这张卡作为那之内的1只）从自己场上解放才能发动。把以那些解放的怪兽为融合素材的1只暗属性融合怪兽从额外卡组特殊召唤。'),
(92719314, 'The Dark Creator', '暗黑创世神', 'ダーク・クリエイター', 'Effect Monster', 'Thunder', 'DARK', 8, 2300, 3000, '这张卡不能通常召唤。自己墓地暗属性怪兽有5只以上存在，自己场上没有怪兽存在的场合可以特殊召唤。可以把自己墓地1只暗属性怪兽从游戏中除外，自己墓地1只暗属性怪兽特殊召唤。这个效果1回合只能使用1次。'),
(30606547, 'The Dark Door', '暗黑之扉', '暗黒の扉', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：双方玩家在战斗阶段只能用1只怪兽攻击。'),
(50237654, 'The Dark Magicians', '超魔导师－黑魔导师徒', '超魔導師－ブラック・マジシャンズ', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 2800, 2300, '「黑魔术师」或「黑魔术少女」＋魔法师族怪兽 ①：1回合1次，魔法·陷阱卡的效果发动的场合才能发动。自己抽1张。那张抽到的卡是魔法·陷阱卡的场合，可以再把那张卡在自己场上盖放。把速攻魔法·陷阱卡盖放的场合，那张卡在盖放的回合也能发动。 ②：这张卡被破坏的场合才能发动。「黑魔术师」「黑魔术少女」各1只从自己的手卡·卡组·墓地特殊召唤。'),
(32245230, 'The Deal of Destiny', '命运的契约', '運命の契約', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：每次自己场上的卡被战斗·效果破坏，给这张卡放置1个皇之键指示物（最多1个）。 ②：对方从额外卡组把怪兽特殊召唤的场合，把这张卡1个皇之键指示物取除才能发动。从手卡·卡组以及自己场上的表侧表示的卡之中把1张「命运之扉」送去墓地，从额外卡组把1只光属性「霍普」超量怪兽当作超量召唤作特殊召唤，把这张卡在那只怪兽下面重叠作为超量素材。'),
(17688543, 'The Deep Grave', '过深的墓穴', '深すぎた墓穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己或者对方的墓地1只怪兽为对象才能发动。下次的自己准备阶段把那只怪兽从墓地往自己场上特殊召唤。'),
(32588805, 'The Despair Uranus', '绝望天王星', 'The despair URANUS', 'Effect Monster', 'Rock', 'LIGHT', 8, 2900, 2300, '①：自己场上没有魔法·陷阱卡存在，这张卡上级召唤成功时才能发动。对方宣言卡的种类（永续魔法·永续陷阱）。自己从卡组选宣言的种类的1张卡在自己的魔法与陷阱区域盖放。 ②：这张卡的攻击力上升自己场上的表侧表示的魔法·陷阱卡数量×300。 ③：只要这张卡在怪兽区域存在，自己的魔法与陷阱区域的表侧表示的卡不会被效果破坏。'),
(27062594, 'The Door of Destiny', '命运之扉', '運命の扉', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能把这张卡发动。那次攻击无效。那之后，这张卡变成效果怪兽（恶魔族·光·1星·攻/守0）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。 ②：这张卡的效果让这张卡已特殊召唤的场合，自己准备阶段从自己墓地把「希望皇 霍普」怪兽任意数量除外才能发动（同名卡最多1张）。给与对方除外数量×500伤害，这张卡的攻击力上升那次伤害的数值。'),
(93346024, 'The Dragon Dwelling in the Cave', '洞穴的潜龙', '洞窟に潜む竜', 'Normal Monster', 'Dragon', 'WIND', 4, 1300, 2000, '洞穴的巨大潜龙。平时很温顺，但生起气来很可怕。据传是在守护财宝。'),
(4404099, 'The Dragon Dwelling in the Deep', '潜伏海底的深海龙', '海底に潜む深海竜', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1700, 1400, '每次双方准备阶段时给这张卡放置1个海洋指示物。这张卡从场上离开时，这张卡放置的海洋指示物每有1个，自己场上存在的鱼族·海龙族怪兽的攻击力直到结束阶段时上升200。'),
(76666602, 'The Dragon that Devours the Dogma', '吞喰圣痕之龙', '聖痕喰らいし竜', 'Fusion Monster', 'Beast', 'DARK', 8, 3000, 2500, '「阿不思的落胤」＋光·暗属性怪兽＋效果怪兽 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。自己·对方的墓地·除外状态的卡合计最多2张回到卡组。 ②：只要自己或对方的场上或墓地有「艾克莉西娅」怪兽存在，这张卡攻击力上升500，不受这张卡以外的效果影响。 ③：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1张「教导」、「铁兽」卡加入手卡。'),
(92408984, 'The Dragon''s Bead', '龙之宝珠', 'ドラゴンの宝珠', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '丢弃1张手卡。以1只表侧表示的龙族怪兽作对象的陷阱卡的效果无效并破坏。'),
(8944575, 'The Drdek', '死亡之足', 'デス・フット', 'Normal Monster', 'Fiend', 'DARK', 3, 700, 800, '眼珠上长着脚的怪兽。高跳着用爪钩攻击。'),
(45445571, 'The Duke of Demise', '死灵公爵', '死霊公爵', 'Fusion Monster', 'Fiend', 'DARK', 6, 2000, 1700, '恶魔族·不死族怪兽×2 这张卡的控制者在每次自己准备阶段支付500基本分或把这张卡破坏。这个卡名的②③的效果1回合各能使用1次。 ①：这张卡不会被战斗破坏。 ②：自己主要阶段才能发动。进行1只怪兽的召唤。 ③：把墓地的这张卡除外，以自己墓地1只4星以上的恶魔族·不死族怪兽为对象才能发动。那只怪兽加入手卡。'),
(66989694, 'The Earl of Demise', '死灵伯爵', '死霊伯爵', 'Normal Monster', 'Fiend', 'DARK', 5, 2000, 700, '魔界的伯爵，外表很绅士，但本性却十分邪恶，不只是人类，连低级的恶魔们都对他感到恐惧。'),
(88696724, 'The Earth - Hex-Sealed Fusion', '融合咒印生物-地', '融合呪印生物－地', 'Effect Monster', 'Rock', 'EARTH', 3, 1000, 1600, '①：这张卡可以作为融合怪兽卡有卡名记述的1只融合素材怪兽的代替。那个时候，其他的融合素材怪兽必须是正规品。 ②：把地属性融合怪兽卡决定的一组融合素材怪兽（这张卡作为那之内的1只）从自己场上解放才能发动。把以那些解放的怪兽为融合素材的1只地属性融合怪兽从额外卡组特殊召唤。'),
(68400115, 'The Emperor''s Holiday', '皇帝的新装', '裸の王様', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '场上的全部装备卡的效果无效。'),
(65403020, 'The End of Anubis', '终结之阿努比斯', 'エンド・オブ・アヌビス', 'Effect Monster', 'Fiend', 'DARK', 6, 2500, NULL, '当这张卡在场上以表侧表示存在时，所有以墓地里的卡为对象的，以及所有在墓地发动的魔法·陷阱·怪兽卡的效果无效。'),
(37706769, 'The Executor of the Underworld - Pluto', '冥府的执行者 普鲁托', '冥府の執行者 プルート', 'Synchro Tuner Monster', 'Fairy', 'DARK', 5, 2300, NULL, '调整＋调整以外的怪兽1只以上 这个卡名在规则上也当作「代行者」卡使用。这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，从自己墓地把1只怪兽除外，以场上1只效果怪兽为对象才能发动。那只怪兽变成里侧守备表示。场上或者墓地有「天空的圣域」存在的场合，这个效果在对方回合也能发动。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地选1张「天空的圣域」加入手卡。'),
(1784686, 'The Eye of Timaeus', '提玛欧斯之眼', 'ティマイオスの眼', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「传说之龙 蒂迈欧」使用。这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「黑魔术」怪兽为对象才能发动。只用那1只怪兽作为融合素材，把有那个卡名作为融合素材记述的1只融合怪兽融合召唤。'),
(34694160, 'The Eye of Truth', '真实之眼', '真実の眼', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，对方把手卡持续公开。对方的准备阶段时对方手卡有魔法卡的场合，对方回复1000基本分。'),
(83039608, 'The Fabled Abanc', '魔轰神兽阿凡可', '魔轟神獣アバンク', 'Tuner Monster', 'Beast', 'LIGHT', 2, 1000, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合才能发动。从手卡选1只「魔轰神」怪兽丢弃，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(68897338, 'The Fabled Behilmoth', '魔轰神兽贝希鲁摩斯', '魔轟神獣ベヒルモス', 'Tuner Monster', 'Beast', 'LIGHT', 2, 1000, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。从手卡选包含这张卡的「魔轰神」怪兽2只以上丢弃，把持有和丢弃的怪兽的原本等级合计相同等级的1只「魔轰神」同调怪兽当作同调召唤从额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，从自己手卡有卡被送去墓地的场合，把这张卡除外才能发动。从手卡把1只「魔轰神」怪兽特殊召唤。'),
(56399890, 'The Fabled Catsith', '魔轰神兽凯西', '魔轟神獣キャシー', 'Tuner Monster', 'Beast', 'LIGHT', 1, 800, 600, '①：这张卡从手卡丢弃去墓地的场合，以场上1张表侧表示卡为对象发动。那张表侧表示卡破坏。'),
(82888408, 'The Fabled Cerburrel', '魔轰神兽刻耳柏拉尔', '魔轟神獣ケルベラル', 'Tuner Monster', 'Beast', 'LIGHT', 2, 1000, 400, '①：这张卡从手卡丢弃去墓地的场合发动。这张卡特殊召唤。'),
(29905795, 'The Fabled Chawa', '魔轰神兽吉娃', '魔轟神獣チャワ', 'Tuner Monster', 'Beast', 'LIGHT', 1, 200, 100, '①：这张卡在手卡存在的场合才能发动。从手卡选1只「魔轰神」怪兽丢弃，这张卡特殊召唤。'),
(18282103, 'The Fabled Ganashia', '魔轰神兽犍那萨', '魔轟神獣ガナシア', 'Effect Monster', 'Beast', 'LIGHT', 3, 1600, 1000, '①：这张卡从手卡丢弃去墓地的场合发动。这张卡特殊召唤。这个效果特殊召唤的这张卡攻击力上升200，从场上离开的场合除外。'),
(26704411, 'The Fabled Kokkator', '魔轰神兽 寇克特', '魔轟神獣コカトル', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 1500, '这张卡战斗破坏对方怪兽送去墓地时，可以从手卡丢弃1只名字带有「魔轰神」的怪兽，从自己卡组抽1张卡。'),
(89194103, 'The Fabled Kudabbi', '魔轰神兽 件', '魔轟神獣クダベ', 'Synchro Monster', 'Beast', 'LIGHT', 4, 2200, 1100, '名字带有「魔轰神」的调整＋调整以外的怪兽1只以上 这张卡得到自己手卡的数量的以下效果。 ●0张：这张卡不会被战斗以及卡的效果破坏。 ●3张以上：结束阶段时这张卡破坏。'),
(55277252, 'The Fabled Nozoochee', '魔轰神兽野槌', '魔轟神獣ノズチ', 'Effect Monster', 'Beast', 'LIGHT', 2, 1200, 800, '①：这张卡在手卡存在的场合才能发动。从手卡选1只「魔轰神」怪兽丢弃，这张卡特殊召唤。 ②：这张卡的①的效果特殊召唤时才能发动。从手卡把1只2星以下的「魔轰神」怪兽特殊召唤。'),
(90616316, 'The Fabled Peggulsus', '魔轰神兽 珀伽拉索斯', '魔轟神獣ペガラサス', 'Tuner Monster', 'Beast', 'LIGHT', 1, 100, 1600, '这张卡从手卡丢弃去墓地时，这张卡可以在自己场上盖放。这张卡反转时，可以把手卡1只名字带有「魔轰神」的怪兽给人观看，从自己卡组把1只名字带有「魔轰神」的怪兽送去墓地。'),
(94845226, 'The Fabled Rubyruda', '魔轰神兽 鲁比拉达', '魔轟神獣ルビィラーダ', 'Tuner Monster', 'Beast', 'LIGHT', 4, 1100, 800, '自己场上表侧表示存在的这张卡被选择作为攻击对象时，可以从手卡丢弃1只名字带有「魔轰神」的怪兽让那次攻击无效。'),
(44155002, 'The Fabled Unicore', '魔轰神兽尤尼科尔', '魔轟神獣ユニコール', 'Synchro Monster', 'Beast', 'LIGHT', 4, 2300, 1000, '「魔轰神」调整＋调整以外的怪兽1只以上 ①：只要这张卡在怪兽区域存在并是双方手卡相同数量，对方发动的魔法·陷阱·怪兽的效果无效化并破坏。'),
(30271097, 'The Fallen &amp; The Virtuous', '落胤与圣女', 'The Fallen ＆ The Virtuous', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「烙印」卡、「教导」卡使用。这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从额外卡组把有「阿不思的落胤」的卡名记述的1只怪兽送去墓地，以场上1张表侧表示卡为对象才能发动。那张卡破坏。 ●自己的场上或墓地有「艾克莉西娅」怪兽存在的场合，以自己或对方的墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(11082056, 'The Fang of Critias', '克里底亚之牙', 'クリティウスの牙', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的卡名在规则上也当作「传说之龙 克里底亚」使用。「克里底亚之牙」在1回合只能发动1张。 ①：「克里底亚之牙」的效果才能特殊召唤的融合怪兽卡记述的1张陷阱卡从自己的手卡·场上送去墓地（那张卡在场上盖放的场合，翻开确认）。那之后，把那1只融合怪兽从额外卡组特殊召唤。'),
(66362965, 'The Fiend Megacyber', '魔导电子巨人', '魔導ギガサイバー', 'Effect Monster', 'Warrior', 'DARK', 6, 2200, 1200, '①：自己场上的怪兽数量比对方场上的怪兽少2只以上的场合，这张卡可以从手卡特殊召唤。'),
(4167084, 'The First Darklord', '黎明的堕天使 路西菲尔', '黎明の堕天使ルシフェル', 'Fusion Monster', 'Fairy', 'DARK', 12, 4000, 4000, '天使族·暗属性怪兽×3 这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：「堕天使 路西菲尔」作为素材让这张卡融合召唤成功的场合才能发动。对方场上的卡全部破坏。 ②：只要这张卡在怪兽区域存在，自己场上的天使族怪兽不会成为对方的效果的对象。 ③：自己·对方的主要阶段支付1000基本分才能发动。从自己的手卡·墓地选1只天使族怪兽守备表示特殊召唤。'),
(8522996, 'The First Monarch', '始源的帝王', '始源の帝王', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（恶魔族·暗·6星·攻1000/守2400）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。 ②：这张卡的效果让这张卡特殊召唤的场合，丢弃1张手卡，宣言1个属性才能发动。这张卡当作宣言的属性使用，和这张卡相同属性的怪兽上级召唤的场合，可以作为2只的数量解放。 ③：只要这张卡的效果特殊召唤的这张卡存在，自己不是和这张卡相同属性的怪兽不能特殊召唤。'),
(31076103, 'The First Sarcophagus', '第一之棺', '第一の棺', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '在对方的每1个结束阶段时，按照「第二之棺」「第三之棺」的顺序将其中1张卡从自己的手卡·卡组以表侧表示放到自己场上。当其中任意1张离场时，将这些卡全部送去墓地。当自己场上凑齐所有卡时，将这些卡全部送去墓地，从自己的手卡·卡组特殊召唤1只「法老之灵」上场。'),
(43973174, 'The Flute of Summoning Dragon', '唤龙笛', 'ドラゴンを呼ぶ笛', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡把最多2只龙族怪兽特殊召唤。这个效果在场上有「龙之支配者」存在的场合才能发动和处理。'),
(20065322, 'The Flute of Summoning Kuriboh', '栗子球的呼唤笛', 'クリボーを呼ぶ笛', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己卡组1只「栗子球」或「羽翼栗子球」，加入手卡或者在自己场上特殊召唤。'),
(94861297, 'The Forceful Checkpoint', '检问', '検問', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方手卡全部确认，那之中有怪兽卡的场合，那次攻击无效。那之后，自己从对方手卡选1只怪兽丢弃。'),
(42829885, 'The Forceful Sentry', '强引的番兵', '強引な番兵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把对方手卡确认，从那之中选1张卡回到卡组。'),
(29826127, 'The Forces of Darkness', '来自暗黑的军势', '暗黒よりの軍勢', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只「暗黑界」怪兽为对象才能发动。那些怪兽加入手卡。'),
(84080939, 'The Forgiving Maiden', '大慈大悲的修女', '慈悲深き修道女', 'Effect Monster', 'Fairy', 'LIGHT', 4, 850, 2000, NULL),
(92223641, 'The Fountain in the Sky', '天空之泉', '天空の泉', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '光属性怪兽被战斗破坏送去自己墓地时，可以把那1只怪兽从游戏中除外，自己基本分回复那只怪兽的攻击力的数值。'),
(18710707, 'The Furious Sea King', '愤怒的海王', '怒りの海王', 'Normal Monster', 'Aqua', 'WATER', 3, 800, 700, '伟大的海之王。唤起永不停息的大海啸将敌人吞没。'),
(33017655, 'The Gates of Dark World', '暗黑界之门', '暗黒界の門', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的恶魔族怪兽的攻击力·守备力上升300。 ②：1回合1次，从自己墓地把1只恶魔族怪兽除外才能发动。从手卡选1只恶魔族怪兽丢弃。那之后，自己从卡组抽1张。'),
(22283204, 'The Gaze of Timaeus', '提玛欧斯之眼光', 'ティマイオスの眼光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的场上·墓地1只「黑魔术师」或「黑魔术少女」为对象才能发动。只用那1只怪兽作为融合素材回到卡组，把有那个卡名作为融合素材记述的1只融合怪兽当作「蒂迈欧之眼」的效果作融合召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段除外。'),
(5915629, 'The Gift of Greed', '强欲的赠物', '強欲な贈り物', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方从卡组抽2张卡。'),
(42671151, 'The Golden Apples', '弗丽嘉的苹果', 'フリッグのリンゴ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有怪兽存在，自己受到战斗伤害时才能发动。自己基本分回复受到的伤害的数值，在自己场上把1只「邪精衍生物」（恶魔族·暗·1星·攻/守?）特殊召唤。这衍生物的攻击力·守备力变成和这个效果让自己回复的数值相同。'),
(82489470, 'The Golden Swordsoul', '轩辕的相剑师', '軒轅の相剣師', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 1800, 1500, '这个卡名的②的效果1回合只能使用1次。 ①：怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤，那次攻击无效。自己场上有需以「阿不思的落胤」为融合素材的融合怪兽存在的场合，可以再把那只攻击宣言的怪兽破坏。 ②：怪兽被表侧表示除外的场合，把场上·墓地的这张卡除外才能发动。从自己的手卡·墓地把攻击力和守备力的数值相同的1只魔法师族·光属性怪兽特殊召唤。'),
(16255173, 'The Grand Jupiter', '宏大木星', 'The grand JUPITER', 'Effect Monster', 'Warrior', 'DARK', 8, 2500, 2000, '①：1回合1次，丢弃2张手卡，以对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的原本攻击力数值。 ③：自己·对方的结束阶段，以这张卡的效果装备的1张怪兽卡为对象才能发动。那张卡在自己场上特殊召唤。'),
(33981008, 'The Grand Spellbook Tower', '魔导书院 拉迈松', '魔導書院ラメイソン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上或者自己墓地有魔法师族怪兽存在的场合，自己准备阶段才能发动。从自己墓地选「魔导书院 拉迈松」以外的1张「魔导书」魔法卡回到卡组最下面，自己从卡组抽1张。 ②：这张卡被对方破坏送去墓地时才能发动。把持有自己墓地的「魔导书」魔法卡数量以下的等级的1只魔法师族怪兽从手卡·卡组特殊召唤。'),
(84136000, 'The Grave of Enkindling', '复活的墓穴', '復活の墓穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽被战斗破坏送去墓地时发动。自己和对方选择各自的墓地1只怪兽，守备表示在场上特殊召唤。这个效果特殊召唤的怪兽只要在场上表侧表示存在，表示形式不能改变。'),
(88089103, 'The Graveyard in the Fourth Dimension', '四次元之墓', '四次元の墓', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的2只名字含有「LV」的怪兽，加入到自己卡组并且洗切。'),
(83340560, 'The Great Double Casted Caster', '伟大的双咒术师', '偉大なるダブルキャスター', 'Fusion Monster', 'Spellcaster', 'LIGHT', 8, NULL, 2600, '效果怪兽以外的怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升作为这张卡的融合素材的仪式·融合·同调·超量·连接怪兽的原本攻击力的合计数值。 ②：这张卡可以直接攻击。 ③：这张卡被战斗·效果破坏的场合，从自己墓地的怪兽以及除外的自己怪兽之中以效果怪兽以外的1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(6836211, 'The Great Emperor Penguin', '大皇帝企鹅', '大皇帝ペンギン', 'Effect Monster', 'Aqua', 'WATER', 5, 1800, 1500, '①：把这张卡解放才能发动。从卡组把「大皇帝企鹅」以外的最多2只「企鹅」怪兽特殊召唤。'),
(44649322, 'The Great Mikanko Ceremony', '传承之大御巫', '伝承の大御巫', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只「御巫」怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在对方结束阶段回到手卡。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把「传承的大御巫」以外的1张「御巫」卡送去墓地。'),
(67906797, 'The Great Noodle Inversion', '天地返', '天地返し', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己卡组最下面的卡加入手卡。那之后，从自己卡组选1张卡在卡组最下面放置。'),
(68049471, 'The Gross Ghost of Fled Dreams', '梦魔的亡灵', '夢魔の亡霊', 'Normal Monster', 'Fiend', 'DARK', 4, 1300, 1800, '进入熟睡者的梦中吸取其生命力的恶魔，被附身的人无法自己醒来。'),
(94845588, 'The Hallowed Azamina', '圣徒蓟花', '聖なる薊花', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把额外卡组1只「蓟花」融合怪兽给对方观看，那个等级每4星为1张的「罪宝」卡从自己的手卡·场上送去墓地（里侧表示卡翻开确认）。那之后，给人观看的怪兽当作融合召唤作特殊召唤。 ②：这张卡在墓地存在的场合，以自己的场上·墓地1只「蓟花」怪兽为对象才能发动。那只怪兽回到卡组，这张卡加入手卡。'),
(5697558, 'The Hidden City', '地中界 香巴拉', '地中界シャンバラ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「地中族」怪兽加入手卡。 ②：1回合1次，自己主要阶段才能发动。选自己1只里侧守备表示的「地中族」怪兽变成表侧攻击表示或者表侧守备表示。 ③：1回合1次，对方怪兽的攻击宣言时才能发动。选自己1只里侧守备表示的「地中族」怪兽变成表侧攻击表示或者表侧守备表示。那之后，可以把那次攻击无效。'),
(99188141, 'The Huge Revolution is Over', '反大革命', '大革命返し', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：要让场上的卡2张以上破坏的怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并除外。'),
(95642274, 'The Humble Sentry', '谦虚的番兵', '謙虚な番兵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡公开，从那之中选1张卡回到卡组。'),
(1525329, 'The Hunter with 7 Weapons', '有7种武器的猎人', '７つの武器を持つハンター', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 600, '这张卡召唤成功时，宣言1个种族发动。这张卡和宣言的种族的怪兽进行战斗的场合，这张卡的攻击力只在伤害计算时上升1000。'),
(22748199, 'The Ice-Bound God', '神之冰结', '神の氷結', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：场上有水属性怪兽2只以上存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽不能攻击，效果无效化。 ②：这张卡在墓地存在的状态，自己场上有5星以上的水属性怪兽召唤·特殊召唤的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(83764996, 'The Illusory Gentleman', '魔导绅士-J', '魔導紳士－J', 'Normal Monster', 'Spellcaster', 'DARK', 4, 1500, 1600, '穿着奇特、反复无常的做坏事与帮助人。'),
(52035300, 'The Immortal Bushi', '不死武士', '不死武士', 'Effect Monster', 'Warrior', 'DARK', 3, 1200, 600, '①：这张卡只要在怪兽区域存在，不能为战士族怪兽的上级召唤以外而解放。 ②：自己准备阶段有这张卡在墓地存在，自己墓地没有战士族怪兽以外的怪兽存在的场合才能发动。这张卡特殊召唤。这个效果在自己场上没有怪兽存在的场合才能发动和处理。'),
(3461403, 'The Immortal Bushi Mourns the Mortal Body', '不死武士之哀悼', '不死武士の悼み', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己墓地的怪兽变成战士族。 ②：自己·对方的结束阶段才能发动。自己场上的怪兽全部破坏。'),
(84926738, 'The Immortal of Thunder', '雷仙人', '雷仙人', 'Flip Effect Monster', 'Thunder', 'LIGHT', 4, 1500, 1300, '反转：基本分回复3000。这张卡从场上送去墓地的时候，基本分失去5000分。'),
(81820689, 'The Inexperienced Spy', '未熟的密探', '未熟な密偵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '指定对方的1张手卡进行观看。'),
(62849088, 'The Iris Swordsoul', '妖眼的相剑师', '妖眼の相剣師', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，效果被无效化的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：对方把怪兽特殊召唤的场合，可以从以那些怪兽从哪里特殊召唤来对应的以下效果选择1个发动。 ●手卡：从手卡把1只怪兽特殊召唤。 ●卡组：自己从卡组抽2张。 ●额外卡组：从额外卡组特殊召唤的那些怪兽之内的1只破坏。'),
(28003512, 'The Judgement Hand', '审判之手', 'ジャジメント・ザ・ハンド', 'Normal Monster', 'Warrior', 'EARTH', 3, 1400, 700, '用寄宿着神灵的手作最后的判决，给予敌人以猛烈的攻击。'),
(11163040, 'The Kaiju Files', '坏兽的出现记录', '壊獣の出現記録', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次从手卡·墓地有「坏兽」怪兽特殊召唤给这张卡放置1个坏兽指示物（最多5个）。 ②：1回合1次，以场上1只「坏兽」怪兽为对象才能发动。那只怪兽破坏，那之后，原本卡名和破坏的那只怪兽不同的1只「坏兽」怪兽从自己卡组往那个控制者场上特殊召唤。 ③：把坏兽指示物是3个以上的这张卡送去墓地才能发动。从卡组把「坏兽的出现记录」以外的1张「坏兽」魔法·陷阱卡加入手卡。'),
(90407382, 'The Kick Man', '蹴杀者', 'ザ・キックマン', 'Effect Monster', 'Zombie', 'DARK', 3, 1300, 300, '这张卡特殊召唤成功时，可以将1张存在于自己墓地里的装备魔法卡装备在这张卡身上。'),
(8978197, 'The King of D.', '龙之主宰－龙的统制者', 'ロード・オブ・ドラゴン－ドラゴンの統制者－', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1200, 1100, '①：这张卡只要在怪兽区域存在，卡名当作「龙之支配者」使用。 ②：这张卡召唤成功时，从手卡丢弃1张魔法·陷阱卡才能发动。从卡组把「呼龙笛」「龙觉醒旋律」「龙复活狂奏」的其中1张加入手卡。'),
(40991587, 'The Lady in Wight', '白骨夫人', 'ワイト夫人', 'Effect Monster', 'Zombie', 'DARK', 3, NULL, 2200, '这张卡的卡名只要在墓地存在当作「白骨」使用。此外，只要这张卡在场上表侧表示存在，「白骨夫人」以外的场上的3星以下的不死族怪兽不会被战斗破坏，也不受魔法·陷阱卡的效果影响。'),
(86099788, 'The Last Warrior from Another Planet', '异星的最终战士', '異星の最終戦士', 'Fusion Monster', 'Warrior', 'EARTH', 7, 2350, 2300, '「暗黑英雄 尸魔侠」＋「魔力吸收球体」 这张卡特殊召唤时，其他的自己的场上的怪兽全部破坏。只要这张卡在场上存在，互相的其他的怪兽不能召唤·反转召唤·特殊召唤。'),
(66926224, 'The Law of the Normal', '弱肉一色', '弱肉一色', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡仅当自己场上存在5只2星以下的表侧表示的通常怪兽时才能发动。玩家各自丢弃全部手卡，并破坏场上除2星以下通常怪兽以外的所有卡。'),
(55008284, 'The League of Uniform Nomenclature', '同姓同名同盟', '同姓同名同盟', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只2星以下的通常怪兽发动。从自己卡组把和选择的卡同名的卡尽可能在自己场上特殊召唤。'),
(29265962, 'The League of Uniform Nomenclature Strikes', '同姓同名同盟罢工', '同姓同名同盟罷業', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只表侧表示怪兽为对象才能发动。原本卡名和那只自己怪兽相同的2只怪兽从自己的手卡·卡组·墓地当作装备魔法卡使用给作为对象的怪兽装备。那只怪兽只要这个效果把怪兽2只都装备中，不能攻击，不会被战斗破坏。这张卡的发动后，直到回合结束时自己不是原本种族和作为对象的怪兽相同的怪兽不能特殊召唤。'),
(54120521, 'The Legend of Tickets', '传说之票', 'The Legend of Tickets', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1张卡为对象才能发动。这个回合的结束阶段，作为对象的墓地的卡回到卡组最上面。下次的自己抽卡阶段的通常抽卡变成2张。'),
(58604027, 'The Legendary Exodia Incarnate', '召唤神 艾克佐迪亚', '召喚神エクゾディア', 'Effect Monster', 'Spellcaster', 'DARK', 10, -1, NULL, '这张卡不能通常召唤。把自己场上1只「被封印」怪兽解放的场合才能特殊召唤。 ①：这张卡的攻击力上升自己墓地的「被封印」怪兽数量×1000。 ②：场上的这张卡不受其他卡的效果影响。 ③：自己结束阶段发动。从自己墓地把1只「被封印」怪兽加入手卡。 ④：这张卡被战斗破坏送去墓地时才能发动。手卡的「被封印」怪兽任意数量给对方观看，自己抽出给人观看的数量。'),
(3643300, 'The Legendary Fisherman', '传说的渔人', '伝説のフィッシャーマン', 'Effect Monster', 'Warrior', 'WATER', 5, 1850, 1600, '①：只要场上有「海」存在，场上的这张卡不受魔法卡的效果影响。 ②：只要场上有「海」存在，这张卡不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。'),
(19801646, 'The Legendary Fisherman II', '传说的渔人二世', '伝説のフィッシャーマン二世', 'Effect Monster', 'Warrior', 'WATER', 5, 2200, 1800, '①：这张卡的卡名只要在场上·墓地存在当作「传说的渔人」使用。 ②：只要场上有「海」存在，场上的这张卡不受其他怪兽的效果影响。 ③：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。从卡组把1只水属性·7星怪兽加入手卡。'),
(44968687, 'The Legendary Fisherman III', '传说的渔人三世', '伝説のフィッシャーマン三世', 'Effect Monster', 'Warrior', 'WATER', 7, 2500, 2000, '这张卡不能通常召唤。把自己场上1只「传说的渔人」解放的场合才能特殊召唤。 ①：这张卡特殊召唤成功时才能发动。对方场上的怪兽全部除外。这个回合，这张卡不能攻击。 ②：场上的这张卡不会被战斗·效果破坏，不受魔法·陷阱卡的效果影响。 ③：1回合1次，自己主要阶段才能发动。除外的对方的卡全部回到墓地，这个回合，对方受到的战斗·效果伤害只有1次变成2倍。'),
(15717011, 'The Light - Hex-Sealed Fusion', '融合咒印生物－光', '融合呪印生物－光', 'Effect Monster', 'Rock', 'LIGHT', 3, 1000, 1600, '这张卡可以作为1只融合素材怪兽的代替。那个时候，其他的融合素材怪兽必须是正规品。此外，把需要的融合素材怪兽（包含这张卡）解放才能发动。把以那些解放的怪兽为融合素材的1只光属性的融合怪兽从额外卡组特殊召唤。'),
(25109950, 'The Little Swordsman of Aile', '艾尔的小剑士', 'アイルの小剣士', 'Effect Monster', 'Warrior', 'WATER', 3, 800, 1300, '每用自己场上存在的这张卡以外的1只怪兽做祭品，这张卡的攻击力在回合结束前加700。'),
(97522863, 'The Man with the Mark', '拥有刻印之人', '刻印を持つ者', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1000, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组选1张「王家的神殿」或者有那个卡名记述的魔法·陷阱卡加入手卡或送去墓地。 ②：只要自己场上有「王家的神殿」存在，这张卡以及自己场上的「阿匹卜」怪兽不会被战斗·效果破坏。 ③：只要这张卡在怪兽区域存在，自己场上的「王家的神殿」不会被效果破坏。'),
(22610082, 'The Mask of Remnants', '遗言之假面', '遺言の仮面', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡回到持有者卡组。 ②：这张卡用「假面魔兽 死亡护法师」的效果装备中的场合，得到装备怪兽的控制权。'),
(49064413, 'The Masked Beast', '假面魔兽 鬼面修道士', '仮面魔獣マスクド・ヘルレイザー', 'Ritual Monster', 'Fiend', 'DARK', 8, 3200, 1800, '「假面魔兽的仪式」降临。'),
(48800175, 'The Melody of Awakening Dragon', '龙之觉醒旋律', 'ドラゴン・目覚めの旋律', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。把最多2只攻击力3000以上而守备力2500以下的龙族怪兽从卡组加入手卡。'),
(98898173, 'The Melting Red Shadow', '溶化的赤影', 'とろける赤き影', 'Normal Monster', 'Aqua', 'WATER', 2, 500, 700, '融化身体藏在脚下的影子里，从敌人的正下方发动攻击。'),
(26822796, 'The Monarchs Awaken', '帝王的冻志', '帝王の凍志', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的额外卡组没有卡存在的场合，以自己场上1只上级召唤的表侧表示怪兽为对象才能发动。那只怪兽效果无效，不受这张卡以外的效果影响。'),
(48716527, 'The Monarchs Erupt', '帝王的溶击', '帝王の溶撃', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的额外卡组没有卡存在，自己场上有上级召唤的怪兽存在的场合才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，上级召唤的怪兽以外的场上的表侧表示怪兽的效果无效化。 ②：自己结束阶段，上级召唤的怪兽不在自己场上存在的场合这张卡送去墓地。'),
(63899196, 'The Monarchs Masterplan', '帝王的策略', '帝王の策略', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从卡组把「帝王的策略」以外的1张「帝王」魔法·陷阱卡送去墓地。 ②：这张卡被除外的场合，以对方场上1只表侧表示怪兽为对象才能发动。属性和那只怪兽相同而攻击力2400/守备力1000的1只怪兽从自己的卡组·墓地加入手卡。那之后，以下效果可以适用。 ●进行「雷帝 扎博尔格」「冰帝 美比乌斯」「炎帝 泰斯塔罗斯」「地帝 格兰玛格」「风帝 莱扎」「邪帝 盖乌斯」的其中1只的召唤。'),
(9283801, 'The Monarchs Revolt', '叛逆的帝王', '叛逆の帝王', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。攻击力是2400以上或800而守备力是1000的卡组3只怪兽给对方观看，对方从那之中选1只。那1只怪兽加入自己手卡，剩余送去墓地。这张卡的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。从手卡把1只攻击力800/守备力1000的怪兽特殊召唤。'),
(79844764, 'The Monarchs Stormforth', '帝王的烈旋', '帝王の烈旋', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能从额外卡组把怪兽特殊召唤。 ①：这个回合，自己把怪兽上级召唤的场合只有1次，可以作为自己场上1只怪兽的代替而把对方场上1只怪兽解放。'),
(8794055, 'The Most Distant, Deepest Depths', '至深魊宙', '最果ての宇宙', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有鱼族同调怪兽存在，这张卡不会被效果破坏，不能用效果除外。 ②：从自己的手卡·墓地把1只鱼族怪兽除外才能发动。从卡组把1只「魊影」怪兽加入手卡。 ③：这张卡在墓地存在的状态，自己场上有鱼族怪兽召唤·特殊召唤的场合，以自己场上1只鱼族怪兽为对象才能发动。那只怪兽除外，这张卡加入手卡。'),
(50433147, 'The Nordic Lights', '极星的光辉', '極星の輝き', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上名字带有「极星」的怪兽不会被战斗破坏。场上的这张卡被破坏时，场上表侧表示存在的名字带有「极星」的怪兽全部破坏。'),
(50470982, 'The Paths of Destiny', '命运的分岔道', '運命の分かれ道', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '双方玩家各自进行1次投掷硬币。出现表侧的场合回复2000基本分，出现里侧的场合基本分受到2000分伤害。'),
(90432163, 'The Phantom Knights of Ancient Cloak', '魅影骑士团沾尘袍', '幻影騎士団ダスティローブ', 'Effect Monster', 'Warrior', 'DARK', 3, 800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在场上攻击表示存在的场合，以场上1只暗属性怪兽为对象才能发动。这张卡变成守备表示，作为对象的怪兽的攻击力·守备力直到对方回合结束时上升800。 ②：把墓地的这张卡除外才能发动。从卡组把「幻影骑士团 沾尘袍」以外的1张「幻影骑士团」卡加入手卡。'),
(62709239, 'The Phantom Knights of Break Sword', '魅影骑士团断碎剑', '幻影騎士団ブレイクソード', 'XYZ Monster', 'Warrior', 'DARK', 3, 2000, 1000, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。 ②：超量召唤的这张卡被破坏的场合，以自己墓地2只相同等级的「幻影骑士团」怪兽为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽的等级上升1星。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。'),
(99315585, 'The Phantom Knights of Cloven Helm', '魅影骑士团裂头盔', '幻影騎士団クラックヘルム', 'Effect Monster', 'Warrior', 'DARK', 4, 1500, 500, '「幻影骑士团 裂头盔」的①②的效果1回合各能使用1次。 ①：「幻影骑士团」卡或者「幻影」魔法·陷阱卡被送去自己墓地的场合发动。这张卡的攻击力上升500。 ②：把墓地的这张卡除外才能发动。这个回合的结束阶段，从自己墓地选1张「幻影骑士团」卡或者「幻影」魔法·陷阱卡加入手卡。'),
(12219047, 'The Phantom Knights of Cursed Javelin', '幻影骑士团 诅咒标枪', '幻影騎士団カースド・ジャベリン', 'XYZ Monster', 'Warrior', 'DARK', 2, 1600, NULL, '2星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动（这张卡有「幻影骑士团」卡在作为超量素材的场合，这个效果在对方回合也能发动）。那只怪兽直到回合结束时攻击力变成0，效果无效化。'),
(24212820, 'The Phantom Knights of Dark Gauntlets', '幻影骑士团 暗黑手甲', '幻影騎士団ダーク・ガントレット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1张「幻影」魔法·陷阱卡送去墓地。 ②：自己场上没有卡存在的场合，对方怪兽的直接攻击宣言时才能在墓地发动。这张卡变成效果怪兽（战士族·暗·4星·攻300/守600）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡从场上离开的场合除外。 ③：这张卡的效果特殊召唤的这张卡的守备力上升自己墓地的「幻影」魔法·陷阱卡数量×300。'),
(36704180, 'The Phantom Knights of Fragile Armor', '魅影骑士团脆铠甲', '幻影騎士団フラジャイルアーマー', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 2000, '「幻影骑士团 脆铠甲」的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的「幻影骑士团」怪兽被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：把墓地的这张卡除外，把手卡1张「幻影骑士团」卡或者「幻影」魔法·陷阱卡送去墓地才能发动。自己从卡组抽1张。'),
(36247316, 'The Phantom Knights of Lost Vambrace', '幻影骑士团 失落护臂甲', '幻影騎士団ロスト・ヴァンブレイズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力下降600，等级变成2星，自己的「幻影骑士团」怪兽不会被战斗破坏。那之后，这张卡变成通常怪兽（战士族·暗·2星·攻600/守0）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。'),
(9336190, 'The Phantom Knights of Mist Claws', '幻影骑士团 雾鸦爪', '幻影騎士団ミストクロウズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以除外的1只自己的「幻影骑士团」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡在墓地存在的场合，对方的直接攻击宣言时以自己墓地1只4星以下的「幻影骑士团」怪兽为对象才能发动。那只怪兽特殊召唤，这张卡变成持有和那只怪兽相同原本等级的通常怪兽（战士族·暗·攻/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(63821877, 'The Phantom Knights of Ragged Gloves', '魅影骑士团破手套', '幻影騎士団ラギッドグローブ', 'Effect Monster', 'Warrior', 'DARK', 3, 1000, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为素材作超量召唤的暗属性怪兽得到以下效果。 ●这次超量召唤成功的场合发动。这张卡的攻击力上升1000。 ②：把墓地的这张卡除外才能发动。从卡组把1张「幻影骑士团」卡或者「幻影」魔法·陷阱卡送去墓地。'),
(26692769, 'The Phantom Knights of Rusty Bardiche', '魅影骑士团锈蚀月刃斧', '幻影騎士団ラスティ・バルディッシュ', 'Link Monster', 'Warrior', 'DARK', NULL, 2100, NULL, '暗属性怪兽2只以上 这张卡不能作为连接素材。这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把1只「幻影骑士团」怪兽送去墓地。那之后，从卡组把1张「幻影」魔法·陷阱卡在自己的魔法与陷阱区域盖放。 ②：这张卡在怪兽区域存在的状态，这张卡所连接区有暗属性超量怪兽特殊召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(98827725, 'The Phantom Knights of Shade Brigandine', '魅影骑士团暗影铠甲', '幻影騎士団シェード・ブリガンダイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己墓地没有陷阱卡存在的场合，这张卡在盖放的回合也能发动。 ①：这张卡发动后变成通常怪兽（战士族·暗·4星·攻0/守300）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。'),
(77462146, 'The Phantom Knights of Shadow Veil', '幻影骑士团 影佑', '幻影騎士団シャドーベイル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力上升300。 ②：这张卡在墓地存在的场合，对方的直接攻击宣言时才能发动。这张卡变成通常怪兽（战士族·暗·4星·攻0/守300）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(36426778, 'The Phantom Knights of Silent Boots', '魅影骑士团无声靴', '幻影騎士団サイレントブーツ', 'Effect Monster', 'Warrior', 'DARK', 3, 200, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「幻影骑士团」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1张「幻影」魔法·陷阱卡加入手卡。'),
(88544390, 'The Phantom Knights of Stained Greaves', '魅影骑士团脏胫甲', '幻影騎士団ステンドグリーブ', 'Effect Monster', 'Warrior', 'DARK', 3, 1200, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「幻影骑士团」怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。那之后，可以让这张卡的等级上升1星。 ②：把墓地的这张卡除外才能发动。从手卡把「幻影骑士团 污痕胫甲」以外的1只「幻影骑士团」怪兽特殊召唤。那之后，可以让那只怪兽的等级上升1星。');